  "arms": [
    {
      "description": "BRAF V600E-Positive Metastatic Melanoma: Patients aged ≥ 18 years with histologically confirmed inoperable metastatic melanoma presenting with a documented BRAF V600E mutation (at primary diagnosis or disease relapse).\n\nA target cohort of 10 participants will undergo serial blood sampling for longitudinal monitoring of BRAF V600E mutation dynamics in cell-free DNA (cfDNA)",
      "id": 1,
      "name": "Arm I (Active Monitoring)",
      "type": {
        "authority": "clinicaltrials.gov",
        "code": "EXPERIMENTAL",
        "display": null,
        "recognized_meaning": null,
        "vocabulary_version": null
      }
    },
    {
      "description": "BRAF V600E-Negative Metastatic Melanoma: Control group consisting of approximately 5 to 7 patients aged ≥ 18 years with histologically confirmed inoperable metastatic melanoma who are negative for the BRAF V600E mutation (BRAF wild-type).\n\nParticipants undergo an identical serial blood sampling protocol to evaluate background signal, analytical specificity, and diagnostic performance.",
      "id": 2,
      "name": "Arm II (Control)",
      "type": {
        "authority": "clinicaltrials.gov",
