  },
  "enrollment": 17,
  "interventions": [
    {
      "description": "Experimental diagnostic platform utilizing the CRISPR/Cas12a system for selective enzymatic degradation of wild-type (WT) DNA sequences, followed by isothermal nucleic acid amplification (LAMP) and end-point electrochemical signal detection on microelectrode chips. Designed for sensitive and specific detection of the BRAF V600E mutation in circulating cell-free DNA (cfDNA) isolated from plasma.",
      "id": 1,
      "name": "Novel CRISPR/Cas12a Electrochemical Bioassay",
      "other_names": [],
      "type": {
        "authority": "clinicaltrials.gov",
        "code": "DIAGNOSTIC_TEST",
        "display": null,
        "recognized_meaning": null,
        "vocabulary_version": null
      }
    },
    {
      "description": "Baseline baseline characterization of tumor tissue mutation status using Next-Generation Sequencing (NGS), accompanied by droplet digital PCR (ddPCR) for orthogonal measurement and quantitation of BRAF V600E allele frequency in circulating tumor DNA (ctDNA). Serves as the reference clinical comparator for evaluating sensitivity and specificity.",
      "id": 2,
      "name": "Reference Standard Molecular Diagnostics (NGS and ddPCR)",
      "other_names": [],
      "type": {
        "authority": "clinicaltrials.gov",
        "code": "DIAGNOSTIC_TEST",
        "display": null,
        "recognized_meaning": null,
        "vocabulary_version": null
      }
    },
    {
      "description": "Venipuncture collecting 10 mL of peripheral blood into dedicated blood collection tubes at two specified clinical timepoints: Day 1 (prior to treatment initiation) and Day 1 + 6 months during ongoing therapy. Collected blood samples undergo immediate plasma isolation and cfDNA extraction.",
      "id": 3,
      "name": "Serial Peripheral Blood Sampling for Liquid Biopsy",
      "other_names": [],
      "type": {
        "authority": "clinicaltrials.gov",
        "code": "PROCEDURE",
        "display": null,
        "recognized_meaning": null,
        "vocabulary_version": null
      }
    }
  ],
  "nct_id": "NCT07870265",
  "phase": "NA",
  "source": "ClinicalTrials.gov",
  "sponsor": "Masaryk Memorial Cancer Institute",
  "start_date": "2026-10-20",
  "status": "RECRUITING",
  "study_type": "INTERVENTIONAL",
  "summary": "The goal of this prospective, low-interventional study is to develop and optimize a highly sensitive and specific method for the detection of the BRAF V600E mutation in liquid biopsy samples from patients with unresectable metastatic melanoma after disease relapse. The method will be based on a CRISPR/Cas12a system combined with isothermal amplification and endpoint electrochemical detection using electrode chips and low-cost instrumentation.",
  "title": "Detection of the BRAF V600E Mutation in Liquid Biopsy Using the CRISPR/Cas12a System"
}
